parts.text:
{
  "feasible": true,
  "summary": "Se añadirá el campo opcional NIF a los clientes. Esto incluye la actualización del esquema de la base de datos, las validaciones del formulario de alta/edición, y la visualización del NIF tanto en la lista general de clientes como en la página de detalle de cada cliente.",
  "assumptions": [
    "El campo NIF se tratará como un campo de texto opcional (nullable) para mantener retrocompatibilidad con los clientes existentes.",
    "El NIF se mostrará en una nueva columna en la tabla de clientes (/clientes) visible en escritorio.",
    "En la página de detalle del cliente (/clientes/[id]), el NIF se mostrará junto al resto de datos de contacto o información fiscal."
  ],
  "tasks": [
    {
      "title": "Añadir campo nif al esquema de base de datos y validaciones",
      "description": "Modifica src/db/schema.ts para añadir la columna nif como `nif: text()` (nullable) en la tabla `clients`. Actualiza `src/app/(crm)/clientes/validation.ts` para incluir `nif` en el esquema Zod de cliente y en el objeto/array de campos `clientFields`.",
      "files": [
        "src/db/schema.ts",
        "src/app/(crm)/clientes/validation.ts"
      ],
      "references": [
        "src/db/schema.ts",
        "src/app/(crm)/clientes/validation.ts"
      ],
      "acceptanceCriteria": [
        {
          "id": "c1",
          "type": "e2e",
          "text": "La vista previa compila correctamente y se puede acceder a la lista de clientes /clientes cargando la tabla clients-table."
        }
      ]
    },
    {
      "title": "Añadir campo NIF al formulario de alta y edición de clientes",
      "description": "Modifica `src/app/(crm)/clientes/client-form.tsx` para incluir el campo `nif` con data-testid `field-nif`. Asegúrate de que las páginas `nuevo/page.tsx` y `[id]/editar/page.tsx` pasen o reciban el valor de `nif` correctamente.",
      "files": [
        "src/app/(crm)/clientes/client-form.tsx",
        "src/app/(crm)/clientes/[id]/editar/page.tsx"
      ],
      "references": [
        "src/app/(crm)/clientes/client-form.tsx",
        "src/app/(crm)/clientes/[id]/editar/page.tsx"
      ],
      "acceptanceCriteria": [
        {
          "id": "c2",
          "type": "e2e",
          "text": "En /clientes/nuevo aparece el input de NIF con el atributo data-testid='field-nif'."
        }
      ]
    },
    {
      "title": "Mostrar el NIF en la lista y detalle de clientes",
      "description": "Actualiza `src/app/(crm)/clientes/page.tsx` (o su subcomponente de tabla) y `src/app/(crm)/clientes/[id]/page.tsx` para mostrar la información del NIF. También actualiza `src/db/seed.ts` si es necesario para dar valor de NIF de prueba a algún cliente.",
      "files": [
        "src/app/(crm)/clientes/page.tsx",
        "src/app/(crm)/clientes/[id]/page.tsx",
        "src/db/seed.ts"
      ],
      "references": [
        "src/app/(crm)/clientes/page.tsx",
        "src/app/(crm)/clientes/[id]/page.tsx"
      ],
      "acceptanceCriteria": [
        {
          "id": "c3",
          "type": "e2e",
          "text": "En /clientes la tabla clients-table contiene la columna NIF."
        },
        {
          "id": "c4",
          "type": "visual",
          "text": "En las capturas de clientes y cliente-detalle se visualiza el campo/columna NIF correctamente integrado en el diseño."
        }
      ]
    }
  ]
}
